def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
    - Multiplos de 3 son 'Fizz'
    - Multiplos de 5 son 'Buzz'
    - Multiplos de 15 son 'FizzBuzz'
    - Los demás números se convierten a string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = 1
    max_elemento = lista[0]
    racha_actual = 1

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            racha_actual += 1
        else:
            if racha_actual > max_racha:
                max_racha = racha_actual
                max_elemento = lista[i - 1]
            racha_actual = 1

    if racha_actual > max_racha:
        max_racha = racha_actual
        max_elemento = lista[-1]

    return (max_elemento, max_racha)

def mcd(a, b):
    """
    Devuelve el máximo común divisor de dos enteros no negativos.
    El mcd de un número con 0 es ese número.
    """
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def comprimir(s: str) -> str:
    """
    Aplica codificación por repeticiones: 'aaabb' -> 'a3b2'.
    Devuelve la versión comprimida solo si es más corta que la original.
    Si no lo es, devuelve la original sin cambios.
    """
    if not s:
        return s

    # Contar repeticiones de cada carácter
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Construir la cadena comprimida
    compressed = ""
    for char, count in counts.items():
        if count > 1:
            compressed += char + str(count)
        else:
            compressed += char

    # Comparar longitud
    if len(compressed) < len(s):
        return compressed
    else:
        return s

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False si no lo son.
    """
    if not s:
        return True

    open_brackets = {'(', '[', '{'}
    close_brackets = {')', ']', '}'}

    stack = []
    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in close_brackets:
            if not stack:
                return False
            top = stack.pop()
            if top != char:
                return False

    return len(stack) == 0

def suma_digitos(n: int) -> int:
    """Suma los dígitos de un número y repite el proceso hasta quedarse con un solo dígito."""
    while len(str(n)) > 1:
        n = sum(int(digit) for digit in str(n))
    return n


