def anidar(plano: dict) -> dict:
    """
    Recorre un diccionario plano y anida las claves que contengan puntos.

    Ejemplo:
        {'a.b': 1} -> {'a': {'b': 1}}
        {'a.b.c': 2} -> {'a': {'b': {'c': 2}}}
    """
    result = {}
    for key, value in plano.items():
        if '.' in key:
            parts = key.split('.')
            current = result
            for part in parts[:-1]:
                if part not in current:
                    current[part] = {}
                current = current[part]
            current[parts[-1]] = value
        else:
            result[key] = value
    return result

def comprimir(s: str) -> str:
    """Aplica run-length encoding a una string.

    Caracteres que aparecen una sola vez se representan como 'c1'.
    """
    if not s:
        return ""

    result = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            if count == 1:
                result.append(current_char)
            else:
                result.append(f"{current_char}{count}")
            current_char = s[i]
            count = 1

    # Añadir el último grupo
    if count == 1:
        result.append(current_char)
    else:
        result.append(f"{current_char}{count}")

    return "".join(result)

def parsear_query(s: str) -> dict:
    """Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split("&"):
        if "=" in part:
            key, value = part.split("=", 1)
            result[key] = value
    return result

